import { expect, it } from '@jest/globals';

import { extractTranslationStrings } from './extract-translation-strings.function';
import { generateXlf } from './generate-xlf.function';
import { getFrameworkTranslationOrigin } from './get-framework-translation-origin.function';
import { ExtractedTranslationString } from './models/extracted-translation-string.model';
import { FsPath, FsUtilities } from '../../utilities/fs.utilities';
import { Ms } from '../../utilities/ms';
import { resolveZibriRoot } from '../../utilities/resolve-zibri-root.function';

// the file is committed and regenerated by "npm run build", so a string added without a build
// since is what this finds. Scanning the whole package is what a build of every application used
// to pay, which is why the strings ship instead
it('ships the strings its sources mark for translation, as "npm run build" writes them', async () => {
    const root: FsPath = resolveZibriRoot();
    const strings: ExtractedTranslationString[] = await extractTranslationStrings(root, [getFrameworkTranslationOrigin(root)]);
    const shipped: string = await FsUtilities.readFile(FsUtilities.getPath(root, 'translations', 'source.xlf'));

    expect(shipped).toBe(generateXlf(strings));
}, Ms.MINUTE);